import {defaults,loadImage,renderImage} from './engine.js?v=editor-3';

export function setupHome({icon,groups}){
  const descriptions={convert:['이미지 형식 변환','JPG·PNG·WebP, 쓰임에 맞게'],compress:['이미지 압축','품질과 실제 용량을 함께 확인'],resize:['크기 조절','픽셀·비율·소셜 규격으로'],crop:['자르기','자유 영역과 고정 비율 선택'],rotate:['회전 및 반전','90° 회전과 좌우·상하 반전'],adjust:['색상 보정','밝기·대비·채도와 노출 조절'],filters:['사진 필터','일곱 가지 필터와 강도 조절'],detail:['선명도 및 흐림','선명하게, 또는 부드럽게'],text:['텍스트 추가','문구·글꼴·위치 자유롭게'],watermark:['워터마크','텍스트·로고를 여러 장에'],frame:['테두리 및 배경','여백·배경색·둥근 모서리'],regions:['모자이크','선택 영역 모자이크와 흐림'],collage:['이미지 합치기','가로·세로 콜라주 만들기'],batch:['일괄 처리','선택한 사진을 한 장씩 처리'],export:['개별 다운로드','결과 확인 후 내 기기에 저장'],zip:['ZIP 다운로드','완료된 결과를 한 번에 묶기']};
  const host=document.getElementById('tool-directory');
  for(const [groupIndex,[title,tools]] of groups.entries()){const section=document.createElement('section');section.className='directory-group';section.dataset.group=groupIndex;const h=document.createElement('h3');h.textContent=title;section.append(h);const grid=document.createElement('div');grid.className='directory-grid';const names=title==='작업 관리'?['batch','export','zip']:tools.map(t=>t[0]);for(const name of names){const [label,description]=descriptions[name];const b=document.createElement('button');b.className='directory-card';b.dataset.startTool=name==='zip'?'batch':name;b.dataset.directoryTool=name;b.setAttribute('aria-pressed','false');b.setAttribute('aria-label',label+' 도구 열기');const visual=document.createElement('span');visual.className='directory-icon';visual.append(icon(name));const text=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=label;small.textContent=description;text.append(strong,small);const arrow=document.createElement('span');arrow.className='directory-arrow';arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');b.append(visual,text,arrow);grid.append(b);}section.append(grid);host.append(section);}
  const selectCard=card=>{for(const b of host.querySelectorAll('.directory-card'))b.setAttribute('aria-pressed',String(b===card));};
  const selectTool=tool=>{const selected=host.querySelector('[aria-pressed="true"]');if(selected?.dataset.startTool===tool)return;selectCard([...host.querySelectorAll('.directory-card')].find(b=>b.dataset.startTool===tool));};
  const input=document.getElementById('hero-compare'),before=document.getElementById('hero-before'),line=document.getElementById('hero-line');
  function compare(){const n=Number(input.value);before.style.clipPath=`inset(0 ${100-n}% 0 0)`;line.style.left=`${n}%`;document.getElementById('hero-compare-value').textContent=n+'%';input.setAttribute('aria-valuetext',`원본 ${n}%, 편집 결과 ${100-n}%`);}
  input.oninput=compare;compare();
  const photo=document.getElementById('hero-comparison');let dragging=false;
  const move=e=>{const r=photo.getBoundingClientRect();input.value=Math.round(Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)));compare();};
  photo.addEventListener('pointerdown',e=>{dragging=true;photo.setPointerCapture(e.pointerId);move(e);e.preventDefault();});photo.addEventListener('pointermove',e=>{if(dragging)move(e);});photo.addEventListener('pointerup',()=>dragging=false);photo.addEventListener('pointercancel',()=>dragging=false);
  (async()=>{try{const im=await loadImage('/assets/studio-demo.webp'),s=defaults(im.naturalWidth,im.naturalHeight);s.mime='image/png';s.adjust={...s.adjust,exposure:-.3,temperature:20,contrast:12,saturation:-15};s.filter='cinema';s.filterIntensity=65;const r=await renderImage({url:'/assets/studio-demo.webp',w:im.naturalWidth,h:im.naturalHeight,settings:s},{preview:true,maxEdge:1100});const url=URL.createObjectURL(r.blob);document.getElementById('hero-after').src=url;}catch{document.getElementById('hero-compare-note').textContent='비교 이미지를 준비하지 못했습니다. 샘플 이미지 체험을 이용하세요.';input.disabled=true;before.hidden=true;line.hidden=true;}})();
  return {selectCard,selectTool};
}
